package de.corporate.lc.lc.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Entity @Table(name="lc_amendment") public class Amendment{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="lc_id")@com.fasterxml.jackson.annotation.JsonIgnore private LetterOfCredit letterOfCredit;private String amendmentNumber;private LocalDate amendmentDate;private BigDecimal amountIncrease;private BigDecimal amountDecrease;private LocalDate newExpiryDate;private String newExpiryPlace;private LocalDate newLatestShipmentDate;@Column(length=4000)private String changedDocuments;@Column(columnDefinition="text")private String changedGoods;@Column(columnDefinition="text")private String changedConditions;@Column(columnDefinition="text")private String rawMessage;private LocalDateTime importedAt=LocalDateTime.now();public UUID getId(){return id;}public LetterOfCredit getLetterOfCredit(){return letterOfCredit;}public void setLetterOfCredit(LetterOfCredit v){letterOfCredit=v;}public String getAmendmentNumber(){return amendmentNumber;}public void setAmendmentNumber(String v){amendmentNumber=v;}public LocalDate getAmendmentDate(){return amendmentDate;}public void setAmendmentDate(LocalDate v){amendmentDate=v;}public BigDecimal getAmountIncrease(){return amountIncrease;}public void setAmountIncrease(BigDecimal v){amountIncrease=v;}public BigDecimal getAmountDecrease(){return amountDecrease;}public void setAmountDecrease(BigDecimal v){amountDecrease=v;}public LocalDate getNewExpiryDate(){return newExpiryDate;}public void setNewExpiryDate(LocalDate v){newExpiryDate=v;}public String getNewExpiryPlace(){return newExpiryPlace;}public void setNewExpiryPlace(String v){newExpiryPlace=v;}public LocalDate getNewLatestShipmentDate(){return newLatestShipmentDate;}public void setNewLatestShipmentDate(LocalDate v){newLatestShipmentDate=v;}public String getChangedDocuments(){return changedDocuments;}public void setChangedDocuments(String v){changedDocuments=v;}public String getChangedGoods(){return changedGoods;}public void setChangedGoods(String v){changedGoods=v;}public String getChangedConditions(){return changedConditions;}public void setChangedConditions(String v){changedConditions=v;}public String getRawMessage(){return rawMessage;}public void setRawMessage(String v){rawMessage=v;}public LocalDateTime getImportedAt(){return importedAt;}}
